zeros=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==0]
from collections import defaultdict
claims=defaultdict(list)
for r,c in zeros:
 for dr,color in [(-1,6),(0,1),(1,4)]:
  if 0<=r+dr<len(grid): claims[(r+dr,c)].append((color,(r,c)))
conf={k:v for k,v in claims.items() if len({x[0] for x in v})>1}
len(zeros),conf

out=[row[:] for row in grid]
for r,c in zeros:
 for dr,color in [(-1,6),(0,1),(1,4)]:
  rr=r+dr
  if 0<=rr<len(out): out[rr][c]=color
print('\n'.join(' '.join(map(str,row)) for row in out))
